from typing import List, Any

class StackWithMax:
    """Stack that tracks the running maximum in O(1)."""
    def __init__(self) -> None:
        self._data: List[Any] = []
        self._max: List[Any] = []

    def push(self, value: int) -> None:
        self._data.append(value)
        if not self._max or value >= self._max[-1]:
            self._max.append(value)

    def pop(self) -> int:
        v = self._data.pop()
        if v == self._max[-1]:
            self._max.pop()
        return v

    def max(self) -> int:
        """Return the running maximum.

        Examples:
            >>> s = StackWithMax()
            >>> for v in [1, 5, 3, 7]: s.push(v)
            >>> s.max()
            7
        """
        return self._max[-1]

if __name__ == "__main__":
    s = StackWithMax()
    for v in [2, 8, 5, 9, 3]:
        s.push(v)
    print(s.max())

