# Queue :: 
class Queue:
    def __init__(self):
        self._data = []
    def enqueue(self, x):
        self._data.append(x)
    def dequeue(self):
        if not self._data:
            raise IndexError("dequeue from empty queue")
        return self._data.pop(0)
    def is_empty(self):
        return not self._data
    def __len__(self):
        return len(self._data)

if __name__ == "__main__":
