# qx2_to_base :: (255, 36)
def qx2_to_base(n, b):
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    out = ''
    while n:
        out = digits[n % b] + out
        n //= b
    return out

