from typing import List, Any

class IntRingBuffer:
    """Ring buffer specialized for ints with peek semantics."""
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._buf: List[int] = [0] * capacity
        self._head = 0
        self._size = 0

    def push(self, value: int) -> None:
        idx = (self._head + self._size) % self.capacity
        self._buf[idx] = value
        if self._size < self.capacity:
            self._size += 1
        else:
            self._head = (self._head + 1) % self.capacity

    def peek_oldest(self) -> int:
        """Return the oldest value without removing it.

        Examples:
            >>> r = IntRingBuffer(3)
            >>> r.push(7); r.peek_oldest()
            7
        """
        return self._buf[self._head]

    def to_list(self) -> List[int]:
        return [self._buf[(self._head + i) % self.capacity] for i in range(self._size)]

if __name__ == "__main__":
    r = IntRingBuffer(3)
    for v in [1,2,3,4]: r.push(v)
    print(r.to_list())

