from typing import List, Tuple

def trie_words_with_prefix_list(root: dict, prefix: str) -> List[str]:
    """Return all trie words with a given prefix as a sorted list."""
    node = root
    for ch in prefix:
        nxt = node.get(ch)
        if not isinstance(nxt, dict):
            return []
        node = nxt
    out: List[str] = []
    def visit(n: dict, path: str) -> None:
        if n.get("$end"):
            out.append(path)
        for k, v in n.items():
            if k != "$end" and isinstance(v, dict):
                visit(v, path + k)
    visit(node, prefix)
    return sorted(out)

if __name__ == "__main__":
    root = {"$end": False}
    for w in ["ant", "and", "an", "age"]:
        n = root
        for ch in w:
            n = n.setdefault(ch, {"$end": False})
        n["$end"] = True
    print(trie_words_with_prefix_list(root, "an"))

# pretty_duration :: (59,)
def pretty_duration(seconds):
    h, rem = divmod(int(seconds), 3600)
    m, s = divmod(rem, 60)
    parts = []
    if h: parts.append(f'{h}h')
    if m: parts.append(f'{m}m')
    if s or not parts: parts.append(f'{s}s')
    return ' '.join(parts)

if __name__ == '__main__':
    print(pretty_duration((59,)))

