from typing import Dict, Any, Iterable

class Counter2:
    """A second Counter variant with subtract()."""
    def __init__(self) -> None:
        self._c: Dict[Any, int] = {}

    def add(self, items: Iterable[Any]) -> None:
        for it in items:
            self._c[it] = self._c.get(it, 0) + 1

    def subtract(self, items: Iterable[Any]) -> None:
        for it in items:
            self._c[it] = self._c.get(it, 0) - 1
            if self._c[it] <= 0:
                self._c.pop(it, None)

    def get(self, key: Any) -> int:
        return self._c.get(key, 0)

if __name__ == "__main__":
    c = Counter2()
    c.add(['a','a','b'])
    c.subtract(['a'])
    print({k: c.get(k) for k in ['a','b']})

