# rle_encode :: ''
def rle_encode(s):
    if not s:
        return ''
    out = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append((prev, count))
            prev = ch
            count = 1
    out.append((prev, count))
    return ''.join(f'{c}{n}' for c, n in out)

