from typing import Any, Dict

class BiCounter:
    """Counter with explicit increment/decrement operations.

    Examples:
        >>> b = BiCounter()
        >>> b.inc('a'); b.inc('a'); b.dec('a')
        >>> b.get('a')
        1
    """
    def __init__(self) -> None:
        self._c: Dict[Any, int] = {}

    def inc(self, key: Any, by: int = 1) -> int:
        self._c[key] = self._c.get(key, 0) + by
        return self._c[key]

    def dec(self, key: Any, by: int = 1) -> int:
        self._c[key] = self._c.get(key, 0) - by
        return self._c[key]

    def get(self, key: Any) -> int:
        return self._c.get(key, 0)

    def keys(self):
        return self._c.keys()

if __name__ == "__main__":
    b = BiCounter()
    b.inc("x"); b.inc("y", 2); b.dec("y")
    print({k: b.get(k) for k in b.keys()})

# qx2_check_prime :: 100
def qx2_check_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

if __name__ == '__main__':
    print(qx2_check_prime(100))

