# qx2_decompose :: 7
def qx2_decompose(n):
    out = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            out.append(d)
            n //= d
        d += 1
    if n > 1:
        out.append(n)
    return out

if __name__ == '__main__':
    print(qx2_decompose(7))

