# unflatten :: {'a': {'b': {'c': 1}}}
def unflatten(d, sep='.'):
    out = {}
    def walk(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f'{prefix}{sep}{k}' if prefix else k
                walk(key, v)
        else:
            out[prefix] = obj
    walk('', d)
    return out

if __name__ == '__main__':
    print(unflatten({'a': {'b': {'c': 1}}}))

