# qx2_factors :: 0
def qx2_factors(n):
    if n <= 0:
        return []
    out = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            out.append(i)
            if i != n // i:
                out.append(n // i)
        i += 1
    return sorted(out)

if __name__ == '__main__':
    print(qx2_factors(0))

