# compute_factorial :: 10
def compute_factorial(n):
    if n < 0:
        raise ValueError("n must be >= 0")
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

if __name__ == "__main__":
    print(compute_factorial(10))

