    if n < 1: return None
    primes = []
    candidate = 2
    while len(primes) < n:
        is_p = True
        for p in primes:
            if p * p > candidate: break
            if candidate % p == 0: is_p = False; break
        if is_p: primes.append(candidate)
        candidate += 1
    return primes[-1]

