from typing import Any

class MinHeap2:
    """A second min-heap variant using simple list operations."""
    def __init__(self) -> None:
        self._data: list = []

    def push(self, value: int) -> None:
        self._data.append(value)
        i = len(self._data) - 1
        while i > 0:
            p = (i - 1) // 2
            if self._data[p] <= self._data[i]:
                break
            self._data[p], self._data[i] = self._data[i], self._data[p]
            i = p

    def pop(self) -> int:
        if not self._data:
            raise IndexError("empty heap")
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            i = 0
            n = len(self._data)
            while True:
                s = i; l = 2*i+1; r = 2*i+2
                if l < n and self._data[l] < self._data[s]: s = l
                if r < n and self._data[r] < self._data[s]: s = r
                if s == i: break
                self._data[i], self._data[s] = self._data[s], self._data[i]
                i = s
        return top

if __name__ == "__main__":
    h = MinHeap2()
    for v in [3, 1, 2]: h.push(v)
    print(h.pop())

