from typing import Dict, List, Tuple

def trie_to_pairs(root: Dict, prefix: str = "") -> List[Tuple[str, int]]:
    """Flatten a dict-style trie into a list of (word, depth) pairs.

    Args:
        root: The trie root.
        prefix: The current path prefix.

    Returns:
        List of (word, depth) tuples.

    Examples:
        See __main__.
    """
    out: List[Tuple[str, int]] = []
    def visit(node: Dict, path: str, depth: int) -> None:
        if node.get("$end"):
            out.append((path, depth))
        for k, v in node.items():
            if k != "$end" and isinstance(v, dict):
                visit(v, path + k, depth + 1)
    visit(root, prefix, 0)
    return out

if __name__ == "__main__":
    root = {"$end": False}
    for w in ["a", "ab"]:
        node = root
        for ch in w:
            node = node.setdefault(ch, {"$end": False})
        node["$end"] = True
    print(trie_to_pairs(root))

