# cos_sim :: ([1, 1], [2, 2])
def cos_sim(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na = sum(x * x for x in a) ** 0.5
    nb = sum(x * x for x in b) ** 0.5
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)

if __name__ == '__main__':
    print(cos_sim(([1, 1], [2, 2])))

