from typing import Any, List

class TwoStackCircularQueue:
    """A circular queue implemented with a fixed list and a head pointer."""
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.capacity = capacity
        self._buf: List[Any] = [None] * capacity
        self.head = 0
        self.count = 0

    def enqueue(self, value: Any) -> None:
        if self.count == self.capacity:
            raise OverflowError("queue full")
        idx = (self.head + self.count) % self.capacity
        self._buf[idx] = value
        self.count += 1

    def dequeue(self) -> Any:
        if self.count == 0:
            raise IndexError("queue empty")
        v = self._buf[self.head]
        self.head = (self.head + 1) % self.capacity
        self.count -= 1
        return v

    def __len__(self) -> int:
        return self.count

if __name__ == "__main__":
    q = TwoStackCircularQueue(4)
    for v in [1, 2, 3]:
        q.enqueue(v)
    print(q.dequeue(), q.dequeue(), len(q))

