from typing import Deque, Any, Iterator
from collections import deque

class PriorityQueueLite:
    """A queue of (priority, value) pairs that pops by lowest priority."""
    def __init__(self) -> None:
        self._data: list = []

    def push(self, priority: int, value: Any) -> None:
        self._data.append((priority, value))
        self._data.sort(key=lambda pv: pv[0])

    def pop(self) -> Any:
        if not self._data:
            raise IndexError("pop from empty")
        return self._data.pop(0)[1]

    def __len__(self) -> int:
        return len(self._data)

if __name__ == "__main__":
    pq = PriorityQueueLite()
    pq.push(2, "b"); pq.push(1, "a"); pq.push(3, "c")
    print(pq.pop(), pq.pop())

