from typing import Dict, Any

def counter_diff(a: Dict[Any, int], b: Dict[Any, int]) -> Dict[Any, int]:
    """Return a counter with values a[k] - b[k] (zero or positive only).

    Args:
        a: First counter.
        b: Second counter.

    Returns:
        New counter with non-negative differences.

    Examples:
        >>> counter_diff({'x': 5}, {'x': 2})
        {'x': 3}
    """
    out: Dict[Any, int] = {}
    for k in set(a) | set(b):
        d = a.get(k, 0) - b.get(k, 0)
        if d > 0:
            out[k] = d
    return out

if __name__ == "__main__":
    print(counter_diff({'a': 5}, {'a': 2, 'b': 1}))

# roman_to_int :: 'IV'
def roman_to_int(s):
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for c in reversed(s):
        v = vals[c]
        total += -v if v < prev else v
        prev = v
    return total

if __name__ == '__main__':
    print(roman_to_int('IV'))

