from typing import Optional, List

def bst_paths(root: Optional['BSTNode']) -> List[List[int]]:
    """Return all root-to-leaf paths in a BST."""
    out: List[List[int]] = []
    def dfs(node: Optional[BSTNode], path: List[int]) -> None:
        if node is None:
            return
        path.append(node.value)
        if node.left is None and node.right is None:
            out.append(list(path))
        else:
            dfs(node.left, path)
            dfs(node.right, path)
        path.pop()
    dfs(root, [])
    return out

