# cache_results :: 
import functools

def cache_results(func):
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    wrapper.cache_clear = cache.clear
    return wrapper

@cache_results
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

