from typing import Optional, List

def bst_level_order(root: Optional['BSTNode']) -> List[List[object]]:
    """Return the level-order traversal of a BST as a list of lists."""
    from collections import deque
    out: List[List[object]] = []
    if root is None:
        return out
    q = deque([root])
    while q:
        level: List[object] = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(node.value)
            if node.left is not None:
                q.append(node.left)
            if node.right is not None:
                q.append(node.right)
        out.append(level)
    return out

