# flat_dict :: {'a': {'b': {'c': 1}}}
def flat_dict(d, sep='.'):
    out = {}
    def walk(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f'{prefix}{sep}{k}' if prefix else k
                walk(key, v)
        else:
            out[prefix] = obj
    walk('', d)
    return out

if __name__ == '__main__':
    print(flat_dict({'a': {'b': {'c': 1}}}))

