from typing import Dict, List

def trie_longest_common_prefix(words: List[str]) -> str:
    """Find the longest common prefix among a list of words using a trie.

    Args:
        words: The words to examine.

    Returns:
        The longest shared prefix.

    Examples:
        >>> trie_longest_common_prefix(['flower','flow','flight'])
        'fl'
    """
    if not words:
        return ""
    root: Dict = {"$end": False}
    for w in words:
        node = root
        for ch in w:
            if not isinstance(node.get(ch), dict):
                node[ch] = {"$end": False}
            node = node[ch]
        node["$end"] = True
    prefix = ""
    node = root
    while True:
        keys = [k for k in node.keys() if k != "$end"]
        if len(keys) != 1 or node.get("$end"):
            break
        ch = keys[0]
        prefix += ch
        node = node[ch]
    return prefix

if __name__ == "__main__":
    print(trie_longest_common_prefix(['interview','interrupt','intervene']))

